# check-app-pages.ps1 -- load every emitted app page in a browser and report
# the ones that do not come up.
#
# The pages under apps/<name>/web/ are checked-in artifacts regenerated by
# build/build-apps.ps1. Nothing in the standing gate opens one, so a page can
# stop working and stay green indefinitely: on 2026-08-12 three of the 28 were
# inert on main and had been for some time. Two died on a primitive the html
# plug never defined (text_starts_with, called by 17 of the 28) and one on an
# HTML parse error, and none of it was visible from the build.
#
# This is an instrument, not a gate. It is deliberately NOT called from
# build/build.ps1: it needs a browser, it costs a few seconds per page, and
# adding it to what runs every time is the thing we do not do. Run it when you
# touch the html plug, the UI foreword, or a Page chapter.
#
#   pwsh build\check-app-pages.ps1
#   pwsh build\check-app-pages.ps1 -Only chat,piano
#   pwsh build\check-app-pages.ps1 -Keep      # leave the DOM dumps for reading
#
# Exit 0 all pages came up, 1 at least one did not, 2 could not run at all.
[CmdletBinding()]
param(
    [string[]]$Only = @(),
    [switch]$Keep,
    [string]$WorkDir = (Join-Path $env:TEMP "codex-app-pages-$env:USERNAME")
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$Repo = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path

$edge = @(
    "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe",
    "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe",
    "$env:ProgramFiles\Google\Chrome\Application\chrome.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $edge) {
    Write-Host "check-app-pages: no Edge or Chrome found; cannot run" -ForegroundColor Yellow
    exit 2
}

if (Test-Path $WorkDir) { Remove-Item $WorkDir -Recurse -Force }
New-Item -ItemType Directory -Path $WorkDir | Out-Null

# Only the pages build-apps.ps1 GENERATES, discovered by its rule: the
# artifact apps/<dir>/web/<name>.html pairs with the chapter whose base name,
# minus a Page/WebPage suffix and lowercased, equals <name>. The other 46
# artifacts in apps/*/web are orphans with no Page chapter -- gpushow is 40 of
# them -- and they are hand-written canvas demos with no #app to mount into.
# Judging those by this measure reports 19 failures that are not failures.
$pages = @()
foreach ($html in (Get-ChildItem (Join-Path $Repo 'apps\*\web\*.html') | Sort-Object FullName)) {
    $appDir = $html.Directory.Parent
    $want = $html.BaseName.ToLower()
    $chapter = @(Get-ChildItem (Join-Path $appDir.FullName '*.codex') -ErrorAction SilentlyContinue |
        Where-Object { ($_.BaseName -replace '(WebPage|Page)$', '').ToLower() -eq $want -and $_.BaseName -match '(WebPage|Page)$' })
    if (-not $chapter.Count) { continue }
    $pages += $html
}
if ($Only.Count) { $pages = @($pages | Where-Object { $Only -contains $_.Directory.Parent.Name }) }
if (-not $pages.Count) { Write-Host "check-app-pages: no generated pages matched" -ForegroundColor Yellow; exit 2 }

# Serve over HTTP rather than file://. A page that fetches an API behaves
# differently off the filesystem -- chat throws there and is clean over HTTP,
# so a file:// run reports a failure no user can reach. The port is derived
# from the workspace and probed upward, because a fixed port on a shared box
# means one agent's run reports another agent's server (L-SHARED).
$portBase = 8400 + ([Math]::Abs($Repo.GetHashCode()) % 200)
$listener = $null
foreach ($p in $portBase..($portBase + 40)) {
    try {
        $l = [System.Net.HttpListener]::new()
        $l.Prefixes.Add("http://localhost:$p/")
        $l.Start()
        $listener = $l; $port = $p; break
    } catch { }
}
if (-not $listener) { Write-Host "check-app-pages: no free port near $portBase" -ForegroundColor Yellow; exit 2 }

$serverJob = Start-ThreadJob -ScriptBlock {
    param($listener, $Repo)
    $mime = @{ '.html'='text/html;charset=utf-8'; '.css'='text/css'; '.js'='application/javascript'
               '.json'='application/json'; '.png'='image/png'; '.svg'='image/svg+xml'; '.ico'='image/x-icon' }
    while ($listener.IsListening) {
        try { $ctx = $listener.GetContext() } catch { break }
        try {
            $rel = [System.Uri]::UnescapeDataString($ctx.Request.Url.AbsolutePath).TrimStart('/').Replace('/', '\')
            $file = Join-Path $Repo $rel
            if ($file.StartsWith($Repo) -and (Test-Path -PathType Leaf $file)) {
                $bytes = [System.IO.File]::ReadAllBytes($file)
                $ext = [System.IO.Path]::GetExtension($file)
                $ctx.Response.ContentType = if ($mime[$ext]) { $mime[$ext] } else { 'application/octet-stream' }
                $ctx.Response.ContentLength64 = $bytes.Length
                $ctx.Response.OutputStream.Write($bytes, 0, $bytes.Length)
            } else { $ctx.Response.StatusCode = 404 }
        } catch { } finally { try { $ctx.Response.Close() } catch { } }
    }
} -ArgumentList $listener, $Repo

$rows = @()
foreach ($page in $pages) {
    $app = $page.Directory.Parent.Name
    $tag = "$app-$($page.BaseName)"
    $dom = Join-Path $WorkDir "$tag.dom.html"
    $err = Join-Path $WorkDir "$tag.stderr.txt"
    $rel = $page.FullName.Substring($Repo.Length).TrimStart('\').Replace('\', '/')
    $uri = "http://localhost:$port/$rel"

    # --dump-dom prints the DOM after scripts have run, so what comes back is
    # what the page BUILT, not what was emitted. Console output only reaches
    # stderr with --enable-logging, and an uncaught error is the signal that
    # matters: every page that has ever failed here failed with one.
    Start-Process -FilePath $edge -Wait -NoNewWindow `
        -ArgumentList @('--headless=new', '--disable-gpu', '--no-first-run',
                        '--enable-logging=stderr', '--v=0',
                        '--virtual-time-budget=5000', '--dump-dom', $uri) `
        -RedirectStandardOutput $dom -RedirectStandardError $err

    $uncaught = @()
    if (Test-Path $err) {
        foreach ($line in (Get-Content $err)) {
            if ($line -match 'Uncaught [A-Za-z]*Error[^"]*') { $uncaught += $Matches[0].Trim() }
        }
    }
    $uncaught = @($uncaught | Select-Object -Unique)

    $domText = if (Test-Path $dom) { Get-Content -Raw $dom } else { '' }
    $mounted = 0
    if ($domText) {
        $m = [regex]::Match($domText, '(?s)<div id="app">(.*?)</div>\s*<script')
        if (-not $m.Success) { $m = [regex]::Match($domText, '(?s)<div id="app">(.*)</body>') }
        if ($m.Success) { $mounted = ($m.Groups[1].Value -replace '\s', '').Length }
    }

    # Two failure shapes, and only these two. An earlier version of this script
    # also failed a page whose injected CSS looked too small, which flagged
    # fishtank -- a generator that prints a document rather than mounting a
    # themed tree. That verdict was the script being wrong about the app.
    # A page whose app ships a backend cannot be judged by serving files alone:
    # its /api/* calls 404 here and it takes a path it never takes deployed.
    # chat throws exactly that way against this server and is clean against its
    # own. Say so rather than calling it a failure the reader cannot act on, or
    # a pass this run did not earn.
    $hasBackend = Test-Path (Join-Path $page.Directory.FullName 'server.ps1')
    $verdict =
        if ($uncaught.Count -and $hasBackend) { 'needs-backend' }
        elseif ($uncaught.Count) { 'ERROR' }
        elseif ($mounted -lt 200) { 'EMPTY' }
        else { 'ok' }
    $rows += [pscustomobject]@{
        app = $app; page = $page.Name; verdict = $verdict
        mounted = $mounted; detail = ($uncaught -join '; ')
    }
}

try { $listener.Stop(); $listener.Close() } catch { }
if ($serverJob) { Remove-Job -Job $serverJob -Force -ErrorAction SilentlyContinue }

$rows | Sort-Object @{e={$_.verdict -eq 'ok'}}, app |
    Format-Table -AutoSize -Property app, page, verdict, mounted, detail -Wrap

$bad = @($rows | Where-Object { $_.verdict -in @('ERROR', 'EMPTY') })
$unjudged = @($rows | Where-Object { $_.verdict -eq 'needs-backend' })
Write-Host ""
foreach ($u in $unjudged) {
    Write-Host ("check-app-pages: NOT JUDGED -- {0} needs its backend; run it with" -f $u.app) -ForegroundColor Yellow
    Write-Host ("  pwsh apps\{0}\web\server.ps1   then load the page from that server" -f $u.app) -ForegroundColor Yellow
}
if (-not $bad.Count) {
    Write-Host "check-app-pages: OK ($($rows.Count - $unjudged.Count) of $($rows.Count) pages came up, $($unjudged.Count) not judged)" -ForegroundColor Green
    if (-not $Keep) { Remove-Item $WorkDir -Recurse -Force -ErrorAction SilentlyContinue }
    exit 0
}
Write-Host "check-app-pages: FAIL -- $($bad.Count) of $($rows.Count) page(s) did not come up" -ForegroundColor Red
foreach ($b in $bad) {
    Write-Host ("  {0,-12} {1}" -f $b.app, $(if ($b.detail) { $b.detail } else { "mounted $($b.mounted) chars" })) -ForegroundColor Red
}
Write-Host "  Regenerate with: pwsh build\build-apps.ps1 -Only <app>"
Write-Host "  DOM dumps and console output: $WorkDir"
Write-Host ""
exit 1
